PRINT N'Populate RefApipInteractionType table'

IF EXISTS(SELECT * FROM dbo.sysobjects WHERE id = object_id(N'[dbo].[RefApipInteractionType]') and OBJECTPROPERTY(id, N'IsUserTable') = 1)
BEGIN
IF NOT EXISTS (SELECT 1 FROM dbo.[RefApipInteractionType] WHERE [Code] = 'CustomInteraction') BEGIN INSERT INTO dbo.[RefApipInteractionType]([Code], [Description], [Definition], [SortOrder])
VALUES ('CustomInteraction', 'Custom Interaction', 'The custom interaction provides an opportunity for extensibility of this specification to include support for interactions not currently documented.', 1.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefApipInteractionType] 
SET [Description] = 'Custom Interaction', [Definition] = 'The custom interaction provides an opportunity for extensibility of this specification to include support for interactions not currently documented.', [SortOrder] = 1.00 WHERE [Code] = 'CustomInteraction'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefApipInteractionType] WHERE [Code] = 'DrawingInteraction') BEGIN INSERT INTO dbo.[RefApipInteractionType]([Code], [Description], [Definition], [SortOrder])
VALUES ('DrawingInteraction', 'Drawing Interaction', 'The drawing interaction allows the candidate to use a common set of drawing tools to modify a given graphical image (the canvas). It must be bound to a response variable with base-type file and single cardinality. The result is a file in the same format as the original image.', 2.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefApipInteractionType] 
SET [Description] = 'Drawing Interaction', [Definition] = 'The drawing interaction allows the candidate to use a common set of drawing tools to modify a given graphical image (the canvas). It must be bound to a response variable with base-type file and single cardinality. The result is a file in the same format as the original image.', [SortOrder] = 2.00 WHERE [Code] = 'DrawingInteraction'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefApipInteractionType] WHERE [Code] = 'GapMatchInteraction') BEGIN INSERT INTO dbo.[RefApipInteractionType]([Code], [Description], [Definition], [SortOrder])
VALUES ('GapMatchInteraction', 'Gap Match Interaction', 'A gap match interaction contains a number gaps that the candidate can fill from an associated set of choices. The candidate must be able to review the content with the gaps filled in context, as indicated by their choices.', 3.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefApipInteractionType] 
SET [Description] = 'Gap Match Interaction', [Definition] = 'A gap match interaction contains a number gaps that the candidate can fill from an associated set of choices. The candidate must be able to review the content with the gaps filled in context, as indicated by their choices.', [SortOrder] = 3.00 WHERE [Code] = 'GapMatchInteraction'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefApipInteractionType] WHERE [Code] = 'MatchInteraction') BEGIN INSERT INTO dbo.[RefApipInteractionType]([Code], [Description], [Definition], [SortOrder])
VALUES ('MatchInteraction', 'Match Interaction', 'A match interaction presents candidates with two sets of choices and allows them to create associates between pairs of choices in the two sets, but not between pairs of choices in the same set. Further restrictions can still be placed on the allowable associations using the matchMax attribute of the choices.', 4.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefApipInteractionType] 
SET [Description] = 'Match Interaction', [Definition] = 'A match interaction presents candidates with two sets of choices and allows them to create associates between pairs of choices in the two sets, but not between pairs of choices in the same set. Further restrictions can still be placed on the allowable associations using the matchMax attribute of the choices.', [SortOrder] = 4.00 WHERE [Code] = 'MatchInteraction'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefApipInteractionType] WHERE [Code] = 'GraphicGapMatchInteraction') BEGIN INSERT INTO dbo.[RefApipInteractionType]([Code], [Description], [Definition], [SortOrder])
VALUES ('GraphicGapMatchInteraction', 'Graphic Gap Match Interaction', 'A graphic gap-match interaction is a graphical interaction with a set of gaps that are defined as areas (hotspots) of the graphic image and an additional set of gap choices that are defined outside the image. The candidate must associate the gap choices with the gaps in the image and be able to review the image with the gaps filled in context, as indicated by their choices. Care should be taken when designing these interactions to ensure that the gaps in the image are a suitable size to receive the required gap choices. It must be clear to the candidate which hotspot each choice has been associated with. When associated, choices must appear wholly inside the gaps if at all possible and, where overlaps are required, should not hide each other completely. If the candidate indicates the association by positioning the choice over the gap (e.g., drag and drop) the system should ''snap'' it to the nearest position that satisfies these requirements.', 5.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefApipInteractionType] 
SET [Description] = 'Graphic Gap Match Interaction', [Definition] = 'A graphic gap-match interaction is a graphical interaction with a set of gaps that are defined as areas (hotspots) of the graphic image and an additional set of gap choices that are defined outside the image. The candidate must associate the gap choices with the gaps in the image and be able to review the image with the gaps filled in context, as indicated by their choices. Care should be taken when designing these interactions to ensure that the gaps in the image are a suitable size to receive the required gap choices. It must be clear to the candidate which hotspot each choice has been associated with. When associated, choices must appear wholly inside the gaps if at all possible and, where overlaps are required, should not hide each other completely. If the candidate indicates the association by positioning the choice over the gap (e.g., drag and drop) the system should ''snap'' it to the nearest position that satisfies these requirements.', [SortOrder] = 5.00 WHERE [Code] = 'GraphicGapMatchInteraction'  END
