IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '13656') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('13656', 'Carbon Monoxide', 'Carbon monoxide is an odorless, colorless and toxic gas. At lower levels of exposure, CO causes mild effects that are often mistaken for the flu. These symptoms include headaches, dizziness, disorientation, nausea and fatigue. At high levels, CO can cause  death.  The effects of CO exposure can vary greatly from person to person depending on age, overall health and the concentration and length of exposure.', 2.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
