IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '02900') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('02900', 'Mold', 'Molds are part of the natural environment. Outdoors, molds break down dead organic matter such as fallen leaves and dead trees, but indoors, mold growth should be avoided. Molds reproduce by means of tiny spores. Mold may begin growing indoors when mold spores land on surfaces that are wet.  Molds have the potential to cause health problems. Molds produce allergens, irritants, and in some cases, potentially toxic substances (mycotoxins).  Inhaling or touching mold or mold spores may cause allergic reactions in sensitive individuals.', 14.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Mold', [Definition] = 'Molds are part of the natural environment. Outdoors, molds break down dead organic matter such as fallen leaves and dead trees, but indoors, mold growth should be avoided. Molds reproduce by means of tiny spores. Mold may begin growing indoors when mold spores land on surfaces that are wet.  Molds have the potential to cause health problems. Molds produce allergens, irritants, and in some cases, potentially toxic substances (mycotoxins).  Inhaling or touching mold or mold spores may cause allergic reactions in sensitive individuals.', [SortOrder] = 14.00 WHERE [Code] = '02900'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '13667') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('13667', 'Nitrogen Oxides', 'Gases consisting of one molecule of nitrogen and varying numbers of oxygen molecules. Nitrogen oxides are produced in the emissions of vehicle exhausts and from power stations. In the atmosphere, nitrogen oxides can contribute to formation of photochemical ozone (smog), can impair visibility and have health consequences, they are thus considered plants.', 15.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
