IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '02903') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('02903', 'Pesticides', 'A pesticide is any substance or mixture of substances intended for preventing, destroying, repelling, or mitigating any pest. The health effects of pesticides depend on the type of pesticide. Some, such as the organophosphates and carbamates, affect the nervous system. Others may irritate the skin or eyes. Some pesticides may be carcinogens. Others may affect the hormone or endocrine system in the body.', 17.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Pesticides', [Definition] = 'A pesticide is any substance or mixture of substances intended for preventing, destroying, repelling, or mitigating any pest. The health effects of pesticides depend on the type of pesticide. Some, such as the organophosphates and carbamates, affect the nervous system. Others may irritate the skin or eyes. Some pesticides may be carcinogens. Others may affect the hormone or endocrine system in the body.', [SortOrder] = 17.00 WHERE [Code] = '02903'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '13669') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('13669', 'Polychlorinated biphenyls (PCBs)', 'PCBs belong to a broad family of man-made organic chemicals known as chlorinated hydrocarbons. PCBs were domestically manufactured from 1929 until their manufacture was banned in 1979. They have a range of toxicity and vary in consistency from thin, light-colored liquids to yellow or black waxy solids. Due to their non-flammability, chemical stability, high boiling point, and electrical insulating properties, PCBs were used in hundreds of industrial and commercial applications including electrical, heat transfer, and hydraulic equipment.  Caulk containing PCBs was used in some buildings, including schools, in the 1950s through the 1970s. Although no longer commercially produced in the United States, PCBs may be present in products and materials produced before the ban. PCBs have been demonstrated to cause cancer, as well as a variety of other adverse health effects on the immune system, reproductive system, nervous system, and endocrine system.', 18.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Polychlorinated biphenyls (PCBs)', [Definition] = 'PCBs belong to a broad family of man-made organic chemicals known as chlorinated hydrocarbons. PCBs were domestically manufactured from 1929 until their manufacture was banned in 1979. They have a range of toxicity and vary in consistency from thin, light-colored liquids to yellow or black waxy solids. Due to their non-flammability, chemical stability, high boiling point, and electrical insulating properties, PCBs were used in hundreds of industrial and commercial applications including electrical, heat transfer, and hydraulic equipment.  Caulk containing PCBs was used in some buildings, including schools, in the 1950s through the 1970s. Although no longer commercially produced in the United States, PCBs may be present in products and materials produced before the ban. PCBs have been demonstrated to cause cancer, as well as a variety of other adverse health effects on the immune system, reproductive system, nervous system, and endocrine system.', [SortOrder] = 18.00 WHERE [Code] = '13669'  END
