IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '02902') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('02902', 'Radon', 'Radon comes from the natural, radioactive breakdown of uranium in soil, rock and water and gets into the air. Radon gas decays into radioactive particles that can get trapped in the lungs through breathing. As they break down further, these particles release small bursts of energy. This can damage lung tissue and lead to lung cancer.  The most common method used to reduce radon is a vent pipe system and fan, which pulls radon from beneath the building and vents it to the outside.', 20.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Radon', [Definition] = 'Radon comes from the natural, radioactive breakdown of uranium in soil, rock and water and gets into the air. Radon gas decays into radioactive particles that can get trapped in the lungs through breathing. As they break down further, these particles release small bursts of energy. This can damage lung tissue and lead to lung cancer.  The most common method used to reduce radon is a vent pipe system and fan, which pulls radon from beneath the building and vents it to the outside.', [SortOrder] = 20.00 WHERE [Code] = '02902'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '13671') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('13671', 'Refrigerants', 'A refrigerant is a compound used in a heat cycle that reversibly undergoes a phase change from a gas to a liquid. Traditionally, fluorocarbons, especially chlorofluorocarbons were used as refrigerants, but they are being phased out because of their ozone depletion effects. Other refrigerants are ammonia, sulfur dioxide, carbon dioxide, and non-halogenated hydrocarbons such as methane. It is illegal to release refrigerants into the atmosphere (intentional or accidental) because they can cause severe damage to the ozone layer. When CFCs are removed they should be recycled to clean out any contaminants and return it to a usable condition. Refrigerants should never be mixed together. Some CFCs must be managed as hazardous waste even if recycled, and special precautions are required for their transport, depending on the legislation of the country''s government.', 21.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Refrigerants', [Definition] = 'A refrigerant is a compound used in a heat cycle that reversibly undergoes a phase change from a gas to a liquid. Traditionally, fluorocarbons, especially chlorofluorocarbons were used as refrigerants, but they are being phased out because of their ozone depletion effects. Other refrigerants are ammonia, sulfur dioxide, carbon dioxide, and non-halogenated hydrocarbons such as methane. It is illegal to release refrigerants into the atmosphere (intentional or accidental) because they can cause severe damage to the ozone layer. When CFCs are removed they should be recycled to clean out any contaminants and return it to a usable condition. Refrigerants should never be mixed together. Some CFCs must be managed as hazardous waste even if recycled, and special precautions are required for their transport, depending on the legislation of the country''s government.', [SortOrder] = 21.00 WHERE [Code] = '13671'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '13672') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('13672', 'Sediment, sludge, reuse material', 'Waste not regulated as "hazardous" may contain toxic metals such as mercury and lead, etc.', 22.00) END
