IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '13673') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('13673', 'Sulfur dioxide', 'Sulfur dioxide (SO2) is one of a group of highly reactive gasses known as "oxides of sulfur." The largest sources of SO2 emissions are from fossil fuel combustion at power plants and other industrial facilities. Smaller sources of SO2 emissions include industrial processes such as extracting metal from ore, and the burning of high sulfur containing fuels by locomotives, large ships and non-road equipment. SO2 is linked with a number of adverse effects on the respiratory system.', 23.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Sulfur dioxide', [Definition] = 'Sulfur dioxide (SO2) is one of a group of highly reactive gasses known as "oxides of sulfur." The largest sources of SO2 emissions are from fossil fuel combustion at power plants and other industrial facilities. Smaller sources of SO2 emissions include industrial processes such as extracting metal from ore, and the burning of high sulfur containing fuels by locomotives, large ships and non-road equipment. SO2 is linked with a number of adverse effects on the respiratory system.', [SortOrder] = 23.00 WHERE [Code] = '13673'  END
