VALUES ('02901', 'Underground storage tanks (USTs)', 'Underground storage tanks (USTs) is specified as the type of hazardous materials or conditions tested for at a site or building.', 24.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Underground storage tanks (USTs)', [Definition] = 'Underground storage tanks (USTs) is specified as the type of hazardous materials or conditions tested for at a site or building.', [SortOrder] = 24.00 WHERE [Code] = '02901'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '13674') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('13674', 'Vapor intrusion', 'Vapor intrusion is defined as vapor phase migration of volatile organic and/or inorganic compounds into occupied buildings from underlying contaminated ground water and/or soil.', 25.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Vapor intrusion', [Definition] = 'Vapor intrusion is defined as vapor phase migration of volatile organic and/or inorganic compounds into occupied buildings from underlying contaminated ground water and/or soil.', [SortOrder] = 25.00 WHERE [Code] = '13674'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefFacilityHazardousMaterialsOrCondType] WHERE [Code] = '13675') BEGIN INSERT INTO dbo.[RefFacilityHazardousMaterialsOrCondType]([Code], [Description], [Definition], [SortOrder])
VALUES ('13675', 'Volatile organic compounds', 'Volatile organic compounds (VOCs) are emitted as gases from certain solids or liquids. VOCs include a variety of chemicals, some of which may have short- and long-term adverse health effects. Concentrations of many VOCs are consistently higher indoors (up to ten times higher) than outdoors. VOCs are emitted by a wide array of products numbering in the thousands. Examples include: paints and lacquers, paint strippers, cleaning supplies, pesticides, building materials and furnishings, office equipment such as copiers and printers, correction fluids and carbonless copy paper, graphics and craft materials including glues and adhesives, permanent markers and photographic solutions   VOCs can cause eye, nose and throat irritation, headaches, loss of coordination, nausea, damage to liver, kidney and central nervous system.', 26.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFacilityHazardousMaterialsOrCondType] 
SET [Description] = 'Volatile organic compounds', [Definition] = 'Volatile organic compounds (VOCs) are emitted as gases from certain solids or liquids. VOCs include a variety of chemicals, some of which may have short- and long-term adverse health effects. Concentrations of many VOCs are consistently higher indoors (up to ten times higher) than outdoors. VOCs are emitted by a wide array of products numbering in the thousands. Examples include: paints and lacquers, paint strippers, cleaning supplies, pesticides, building materials and furnishings, office equipment such as copiers and printers, correction fluids and carbonless copy paper, graphics and craft materials including glues and adhesives, permanent markers and photographic solutions   VOCs can cause eye, nose and throat irritation, headaches, loss of coordination, nausea, damage to liver, kidney and central nervous system.', [SortOrder] = 26.00 WHERE [Code] = '13675'  END
