IF NOT EXISTS (SELECT 1 FROM dbo.[RefFinancialAccountBalanceSheetCode] WHERE [Code] = '710') BEGIN INSERT INTO dbo.[RefFinancialAccountBalanceSheetCode]([Code], [Description], [Definition], [SortOrder])
VALUES ('710', 'Nonspendable Fund Balance', 'The nonspendable fund balance classification includes amounts that cannot be spent because they are either (a) not in spendable form or (b) legally or contractually required to be maintained intact. This would include items not expected to be converted to cash, including inventories and prepaid amounts. It may also include the long-term amount of loans and receivables, as well as property acquired for resale and the corpus (principal) of a permanent fund.', 76.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFinancialAccountBalanceSheetCode] 
SET [Description] = 'Nonspendable Fund Balance', [Definition] = 'The nonspendable fund balance classification includes amounts that cannot be spent because they are either (a) not in spendable form or (b) legally or contractually required to be maintained intact. This would include items not expected to be converted to cash, including inventories and prepaid amounts. It may also include the long-term amount of loans and receivables, as well as property acquired for resale and the corpus (principal) of a permanent fund.', [SortOrder] = 76.00 WHERE [Code] = '710'  END
