IF NOT EXISTS (SELECT 1 FROM dbo.[RefFinancialAccountBalanceSheetCode] WHERE [Code] = '730') BEGIN INSERT INTO dbo.[RefFinancialAccountBalanceSheetCode]([Code], [Description], [Definition], [SortOrder])
VALUES ('730', 'Committed Fund Balance', 'The committed fund balance classification reflects specific purposes pursuant to constraints imposed by formal action at the district''s highest level of decisionmaking authority (generally the governing board). Such constraints can only be removed or changed by the same form of formal action.', 78.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFinancialAccountBalanceSheetCode] 
