IF NOT EXISTS (SELECT 1 FROM dbo.[RefFinancialAccountBalanceSheetCode] WHERE [Code] = '740') BEGIN INSERT INTO dbo.[RefFinancialAccountBalanceSheetCode]([Code], [Description], [Definition], [SortOrder])
VALUES ('740', 'Assigned Fund Balance', 'The assigned fund balance classification reflects amounts that are constrained by the government''s intent to be used for specific purposes, but meet neither the restricted nor committed forms of constraint. Also, the assigned fund balance classification is the residual classification for the special revenue, debt service, capital projects, and/or permanent funds after nonspendable, restricted, and committed balances have been identified (unless the residual amount is negative, which would require presentation as unassigned fund balance).', 79.00) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefFinancialAccountBalanceSheetCode] 
SET [Description] = 'Assigned Fund Balance', [Definition] = 'The assigned fund balance classification reflects amounts that are constrained by the government''s intent to be used for specific purposes, but meet neither the restricted nor committed forms of constraint. Also, the assigned fund balance classification is the residual classification for the special revenue, debt service, capital projects, and/or permanent funds after nonspendable, restricted, and committed balances have been identified (unless the residual amount is negative, which would require presentation as unassigned fund balance).', [SortOrder] = 79.00 WHERE [Code] = '740'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefFinancialAccountBalanceSheetCode] WHERE [Code] = '750') BEGIN INSERT INTO dbo.[RefFinancialAccountBalanceSheetCode]([Code], [Description], [Definition], [SortOrder])
