IF NOT EXISTS (SELECT 1 FROM dbo.[RefFinancialAccountBalanceSheetCode] WHERE [Code] = '760') BEGIN INSERT INTO dbo.[RefFinancialAccountBalanceSheetCode]([Code], [Description], [Definition], [SortOrder])
