BEGIN
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSFASBRevenue] WHERE [Code] = 'Contributionsfromaffiliatedentities') BEGIN INSERT INTO dbo.[RefIPEDSFASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Contributionsfromaffiliatedentities', 'Contributions from affiliated entities', 'Used for reporting all revenues received from non-consolidated affiliated entities, such as fund raising foundations, booster clubs, other institutionally-related foundations, and similar organizations created to support the institution or organizational components of the institution.', NULL) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefIPEDSFASBRevenue] 
SET [Description] = 'Contributions from affiliated entities', [Definition] = 'Used for reporting all revenues received from non-consolidated affiliated entities, such as fund raising foundations, booster clubs, other institutionally-related foundations, and similar organizations created to support the institution or organizational components of the institution.', [SortOrder] = NULL WHERE [Code] = 'Contributionsfromaffiliatedentities'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSFASBRevenue] WHERE [Code] = 'Federalappropriations') BEGIN INSERT INTO dbo.[RefIPEDSFASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Federalappropriations', 'Federal appropriations', 'Used for reporting all amounts received from the federal government through a direct appropriation of Congress, except grants and contracts. An example of a federal appropriation is a federal land-grant appropriation. Does not include Pell Grants or any ARRA revenues.', NULL) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefIPEDSFASBRevenue] 
SET [Description] = 'Federal appropriations', [Definition] = 'Used for reporting all amounts received from the federal government through a direct appropriation of Congress, except grants and contracts. An example of a federal appropriation is a federal land-grant appropriation. Does not include Pell Grants or any ARRA revenues.', [SortOrder] = NULL WHERE [Code] = 'Federalappropriations'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSFASBRevenue] WHERE [Code] = 'Federalgrantscontracts') BEGIN INSERT INTO dbo.[RefIPEDSFASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Federalgrantscontracts', 'Federal grants and contracts', 'Used for reporting all revenues from federal agencies that are for specific undertakings such as research projects, training projects, and similar activities, including contributions from federal agencies. If federal Pell and similar student aid grants are treated as agency transactions in your GPFS, they are excluded from this amount. If federal Pell and similar student aid grants are treated as student aid expenses or as allowances when awarded, they are included from this amount. Does not include any ARRA revenues.', NULL) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefIPEDSFASBRevenue] 
SET [Description] = 'Federal grants and contracts', [Definition] = 'Used for reporting all revenues from federal agencies that are for specific undertakings such as research projects, training projects, and similar activities, including contributions from federal agencies. If federal Pell and similar student aid grants are treated as agency transactions in your GPFS, they are excluded from this amount. If federal Pell and similar student aid grants are treated as student aid expenses or as allowances when awarded, they are included from this amount. Does not include any ARRA revenues.', [SortOrder] = NULL WHERE [Code] = 'Federalgrantscontracts'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSFASBRevenue] WHERE [Code] = 'Hospitalrevenuenottobereportedby') BEGIN INSERT INTO dbo.[RefIPEDSFASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Hospitalrevenuenottobereportedby', 'Hospital revenue (not to be reported by less-than-4-year institutions)', 'Used for reporting the amount of revenues generated by the auxiliary enterprise operations, net of any allowances applied in the general purpose financial statements. Auxiliary enterprises are operations that exist to furnish a service to students, faculty, or staff, and that charge a fee that is directly related to the cost of the service. Examples are residence halls, food services, student health services, intercollegiate athletics, college unions, college stores, and movie theaters.', NULL) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefIPEDSFASBRevenue] 
SET [Description] = 'Hospital revenue (not to be reported by less-than-4-year institutions)', [Definition] = 'Used for reporting the amount of revenues generated by the auxiliary enterprise operations, net of any allowances applied in the general purpose financial statements. Auxiliary enterprises are operations that exist to furnish a service to students, faculty, or staff, and that charge a fee that is directly related to the cost of the service. Examples are residence halls, food services, student health services, intercollegiate athletics, college unions, college stores, and movie theaters.', [SortOrder] = NULL WHERE [Code] = 'Hospitalrevenuenottobereportedby'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSFASBRevenue] WHERE [Code] = 'Independentoperationsrevenuenottobe') BEGIN INSERT INTO dbo.[RefIPEDSFASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Independentoperationsrevenuenottobe', 'Independent operations revenue (not to be reported by less-than-4-year institutions)', 'Used for reporting the revenues and gains of hospitals operated as a component of a reporting institution of higher education. If your hospital is reporting in IPEDS educational program activity that is conducted separate from an institution of higher education, they are excluded from this amount.', NULL) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefIPEDSFASBRevenue] 
SET [Description] = 'Independent operations revenue (not to be reported by less-than-4-year institutions)', [Definition] = 'Used for reporting the revenues and gains of hospitals operated as a component of a reporting institution of higher education. If your hospital is reporting in IPEDS educational program activity that is conducted separate from an institution of higher education, they are excluded from this amount.', [SortOrder] = NULL WHERE [Code] = 'Independentoperationsrevenuenottobe'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSFASBRevenue] WHERE [Code] = 'Investmentreturn') BEGIN INSERT INTO dbo.[RefIPEDSFASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Investmentreturn', 'Investment return', 'Used for reporting all investment income (i.e., interest, dividends, rents and royalties), gains and losses (realized and unrealized) from holding investments (regardless of the nature of the investment), student loan interest, and amounts distributed from irrevocable trusts held by others (collectively referred to as "investment return"). Changes in the value of interest rate swaps should be included in this amount.', NULL) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefIPEDSFASBRevenue] 
SET [Description] = 'Investment return', [Definition] = 'Used for reporting all investment income (i.e., interest, dividends, rents and royalties), gains and losses (realized and unrealized) from holding investments (regardless of the nature of the investment), student loan interest, and amounts distributed from irrevocable trusts held by others (collectively referred to as "investment return"). Changes in the value of interest rate swaps should be included in this amount.', [SortOrder] = NULL WHERE [Code] = 'Investmentreturn'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSFASBRevenue] WHERE [Code] = 'Localappropriations') BEGIN INSERT INTO dbo.[RefIPEDSFASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Localappropriations', 'Local appropriations', 'Used for reporting all amounts received from a local government (i.e., city and/or county) through a direct appropriation of its legislative body, except for local grants and contracts. An example of a local appropriation is an annual local appropriation for operating expenses of the institution.', NULL) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefIPEDSFASBRevenue] 
SET [Description] = 'Local appropriations', [Definition] = 'Used for reporting all amounts received from a local government (i.e., city and/or county) through a direct appropriation of its legislative body, except for local grants and contracts. An example of a local appropriation is an annual local appropriation for operating expenses of the institution.', [SortOrder] = NULL WHERE [Code] = 'Localappropriations'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSFASBRevenue] WHERE [Code] = 'Localgrantscontracts') BEGIN INSERT INTO dbo.[RefIPEDSFASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Localgrantscontracts', 'Local grants and contracts', 'Used for reporting all revenues from local government agencies that are for specific undertakings such as research projects, training projects, and similar activities, including contributions from local agencies. If local grants for student aid are treated as agency transactions in your GPFS, they are excluded from this amount. If local grants for student aid are treated in your GPFS as student aid expenses or as allowances when awarded, they are included from this amount.', NULL) END
