IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSGASBRevenue] WHERE [Code] = 'Federalappropriations') BEGIN INSERT INTO dbo.[RefIPEDSGASBRevenue]([Code], [Description], [Definition], [SortOrder])
VALUES ('Federalappropriations', 'Federal appropriations', 'Used for reporting all amounts received by the institution through acts of a federal legislative body, except grants and contracts. Funds reported in this category are for meeting current operating expenses, not for specific projects or programs. An example is federal land-grant appropriations. If your institution accounts for land grant appropriations as operating revenue, they are excluded from this amount. Does not include any ARRA revenues.', NULL) END
ELSE IF @updateExisting = 1 BEGIN UPDATE dbo.[RefIPEDSGASBRevenue] 
SET [Description] = 'Federal appropriations', [Definition] = 'Used for reporting all amounts received by the institution through acts of a federal legislative body, except grants and contracts. Funds reported in this category are for meeting current operating expenses, not for specific projects or programs. An example is federal land-grant appropriations. If your institution accounts for land grant appropriations as operating revenue, they are excluded from this amount. Does not include any ARRA revenues.', [SortOrder] = NULL WHERE [Code] = 'Federalappropriations'  END
IF NOT EXISTS (SELECT 1 FROM dbo.[RefIPEDSGASBRevenue] WHERE [Code] = 'Federalnonoperatinggrants') BEGIN INSERT INTO dbo.[RefIPEDSGASBRevenue]([Code], [Description], [Definition], [SortOrder])
