IF NOT EXISTS (SELECT 1 FROM dbo.[RefStudentSupportServiceType] WHERE [Code] = '00294') BEGIN INSERT INTO dbo.[RefStudentSupportServiceType]([Code], [Description], [Definition], [SortOrder])
VALUES ('00294', 'Service coordination (case management services)', 'Activities carried out by service coordinator to assist and enable an eligible student and his/her family to receive the rights, procedural safeguards, and services that are authorized to provided under the State''s early intervention program. The specific activities include: coordinating the performance of evaluations and assessments; facilitating and anticipating in the development, review, and evaluation of individualized family service plans; assisting families in identifying available service providers; coordinating and monitoring the delivery of available services; informing families of the availability of advocacy services; coordinating with medical and health providers; and facilitating the development of a transition plan to preschool services, if appropriate.', 55.00) END
